// Ignore full-SOC readings while in limited mode.
// Without this, SOC drifting 100 -> 99.9 after the balance ends
// would restart the balance and cancel the 14-day timer.
if (flow.get('limitedMode') === true) return null;

if (flow.get('balanceHold') !== true) {
    flow.set('balanceHold', true);
    flow.set('limitedMode', false);
    flow.set('windowOpen', false);
    flow.set('desiredSOC', 100);
    flow.set('fullCycleEnd', 0);
    flow.set('balanceEnd', 0);
    flow.set('fullCycleTimerGeneration', (flow.get('fullCycleTimerGeneration') || 0) + 1);
    flow.set('balanceTimerGeneration', (flow.get('balanceTimerGeneration') || 0) + 1);
    flow.set('clear14DayTimerStatus', true);
    flow.set('clearBalanceTimerStatus', false);

    node.send([{payload: "start_2h"}, {payload: "recalc"}]);
    return null;
}

node.status({});
return null;

flow.set('balanceHold', false);
flow.set('limitedMode', true);
flow.set('windowOpen', false);
flow.set('desiredSOC', 0);

flow.set('balanceEnd', 0);
flow.set('balanceTimerGeneration', (flow.get('balanceTimerGeneration') || 0) + 1);
flow.set('clearBalanceTimerStatus', true);
flow.set('fullCycleEnd', 0);
flow.set('clear14DayTimerStatus', false);

node.status({fill:"green",shape:"dot",text:"Limited mode 30-80"});

node.send([{payload: "recalc"}, {payload: "start_14day"}]);
return null;

flow.set('limitedMode', false);
flow.set('balanceHold', false);
flow.set('windowOpen', false);
flow.set('desiredSOC', 100);
flow.set('balanceEnd', 0);
flow.set('fullCycleEnd', 0);
flow.set('balanceTimerGeneration', (flow.get('balanceTimerGeneration') || 0) + 1);
flow.set('fullCycleTimerGeneration', (flow.get('fullCycleTimerGeneration') || 0) + 1);
flow.set('clearBalanceTimerStatus', true);
flow.set('clear14DayTimerStatus', true);

node.status({});
return {payload: "recalc"};

if (flow.get('limitedMode') !== true) return null;

const windowOpen = flow.get('windowOpen') || false;

if (!windowOpen) {
    flow.set('windowOpen', true);
    flow.set('desiredSOC', 100);
    return {payload: "recalc"};
}
return null;

if (flow.get('limitedMode') !== true) return null;

const windowOpen = flow.get('windowOpen') || false;

if (windowOpen) {
    flow.set('windowOpen', false);
    flow.set('desiredSOC', 0);
    return {payload: "recalc"};
}
return null;

// MANUAL START / FORCE 100A
// Hard-stop BOTH timers and return to normal 100A charging.

// ------------------------------------------------------------
// STOP / INVALIDATE 2-HOUR TIMER
// ------------------------------------------------------------

flow.set(
    'balanceTimerGeneration',
    (flow.get('balanceTimerGeneration') || 0) + 1
);

const balanceTimer = flow.get('balanceTimerHandle');

if (balanceTimer) {
    clearInterval(balanceTimer);
}

flow.set('balanceTimerHandle', null);
flow.set('balanceEnd', 0);

// ------------------------------------------------------------
// STOP / INVALIDATE 14-DAY TIMER
// ------------------------------------------------------------

flow.set(
    'fullCycleTimerGeneration',
    (flow.get('fullCycleTimerGeneration') || 0) + 1
);

const fullCycleTimer = flow.get('fullCycleTimerHandle');

if (fullCycleTimer) {
    clearInterval(fullCycleTimer);
}

flow.set('fullCycleTimerHandle', null);
flow.set('fullCycleEnd', 0);

// ------------------------------------------------------------
// RETURN TO NORMAL 100A MODE
// ------------------------------------------------------------

flow.set('balanceHold', false);
flow.set('limitedMode', false);
flow.set('windowOpen', false);
flow.set('desiredSOC', 100);

// ------------------------------------------------------------
// CLEAR TIMER NODE STATUSES
// ------------------------------------------------------------

// The timer generations/handles above prevent old intervals
// from putting their status back after this button is pressed.

node.status({});

// Recalculate DVCC.
// Cell-voltage protection remains active.
return {payload: "recalc"};

// FORCE LIMITED MODE
// Hard-stop the 2-hour timer.
// Start exactly one fresh 14-day timer.

// ------------------------------------------------------------
// STOP / INVALIDATE 2-HOUR TIMER
// ------------------------------------------------------------

flow.set(
    'balanceTimerGeneration',
    (flow.get('balanceTimerGeneration') || 0) + 1
);

const balanceTimer = flow.get('balanceTimerHandle');

if (balanceTimer) {
    clearInterval(balanceTimer);
}

flow.set('balanceTimerHandle', null);
flow.set('balanceEnd', 0);

// ------------------------------------------------------------
// STOP / INVALIDATE EXISTING 14-DAY TIMER
// ------------------------------------------------------------

flow.set(
    'fullCycleTimerGeneration',
    (flow.get('fullCycleTimerGeneration') || 0) + 1
);

const fullCycleTimer = flow.get('fullCycleTimerHandle');

if (fullCycleTimer) {
    clearInterval(fullCycleTimer);
}

flow.set('fullCycleTimerHandle', null);
flow.set('fullCycleEnd', 0);

// ------------------------------------------------------------
// ENTER LIMITED MODE
// ------------------------------------------------------------

flow.set('balanceHold', false);
flow.set('limitedMode', true);
flow.set('windowOpen', false);
flow.set('desiredSOC', 0);

// ------------------------------------------------------------
// NODE STATUS
// ------------------------------------------------------------

node.status({
    fill: "green",
    shape: "dot",
    text: "Limited mode 30-80"
});

// ------------------------------------------------------------
// OUTPUT 1 → RECALCULATE DVCC
// OUTPUT 2 → START 14-DAY TIMER
// ------------------------------------------------------------

node.send([
    {payload: "recalc"},
    {payload: "start_14day"}
]);

return null;

// 2-hour balance timer.
// ONLY ONE 2-hour timer may exist at a time.
// It may only run while balanceHold is true.

const duration = 2 * 60 * 60 * 1000;
const restoring = msg && msg.payload === "restore_balance";

// ------------------------------------------------------------
// CANCEL / INVALID STATE
// ------------------------------------------------------------

if (flow.get('balanceHold') !== true || flow.get('limitedMode') === true) {

    // Invalidate any existing timer.
    const generation =
        (flow.get('balanceTimerGeneration') || 0) + 1;

    flow.set('balanceTimerGeneration', generation);

    // Clear stored expiration.
    flow.set('balanceEnd', 0);

    // Kill currently running interval.
    const oldTimer = flow.get('balanceTimerHandle');

    if (oldTimer) {
        clearInterval(oldTimer);
        flow.set('balanceTimerHandle', null);
    }

    // No status when timer is cleared.
    node.status({});

    return null;
}

// ------------------------------------------------------------
// STOP ANY PREVIOUS INSTANCE
// ------------------------------------------------------------

const oldTimer = flow.get('balanceTimerHandle');

if (oldTimer) {
    clearInterval(oldTimer);
    flow.set('balanceTimerHandle', null);
}

// ------------------------------------------------------------
// NEW GENERATION
// ------------------------------------------------------------

const generation =
    (flow.get('balanceTimerGeneration') || 0) + 1;

flow.set('balanceTimerGeneration', generation);

// ------------------------------------------------------------
// DETERMINE END TIME
// ------------------------------------------------------------

let end = Number(flow.get('balanceEnd'));

if (!restoring || !Number.isFinite(end) || end <= 0) {
    end = Date.now() + duration;
    flow.set('balanceEnd', end);
}

// ------------------------------------------------------------
// ALREADY EXPIRED
// ------------------------------------------------------------

if (end <= Date.now()) {

    flow.set('balanceEnd', 0);
    flow.set('balanceTimerHandle', null);

    node.status({});

    node.send({payload: "done"});

    return null;
}

// ------------------------------------------------------------
// INITIAL STATUS
// ------------------------------------------------------------

node.status({
    fill: "blue",
    shape: "ring",
    text: restoring
        ? "Balance timer restored"
        : "Starting 2-hour balance timer"
});

// ------------------------------------------------------------
// SINGLE ACTIVE INTERVAL
// ------------------------------------------------------------

const check = setInterval(() => {

    // Make sure this is still the active timer.
    if (
        flow.get('balanceHold') !== true ||
        flow.get('limitedMode') === true ||
        flow.get('balanceTimerGeneration') !== generation ||
        Number(flow.get('balanceEnd')) !== end
    ) {
        clearInterval(check);

        // Only clear the status if this is still
        // the active timer.
        if (flow.get('balanceTimerHandle') === check) {
            flow.set('balanceTimerHandle', null);
            node.status({});
        }

        return;
    }

    const remaining = Math.max(0, end - Date.now());

    // --------------------------------------------------------
    // TIMER FINISHED
    // --------------------------------------------------------

    if (remaining <= 0) {

        clearInterval(check);

        flow.set('balanceEnd', 0);
        flow.set('balanceTimerHandle', null);

        node.status({});

        node.send({payload: "done"});

        return;
    }

    // --------------------------------------------------------
    // DISPLAY REMAINING TIME
    // --------------------------------------------------------

    const mins = Math.ceil(remaining / 60000);

    node.status({
        fill: "blue",
        shape: "ring",
        text: mins + " min left"
    });

}, 5000);

// Store the ONLY active timer handle.
flow.set('balanceTimerHandle', check);

return null;

// 14-day limited-mode timer.
// ONLY ONE 14-day timer may exist at a time.
// It may only run while limitedMode is true.

const duration = 14 * 24 * 60 * 60 * 1000;
const restoring = msg && msg.payload === "restore_14day";

// ------------------------------------------------------------
// CANCEL / INVALID STATE
// ------------------------------------------------------------

if (flow.get('limitedMode') !== true || flow.get('balanceHold') === true) {

    // Invalidate any existing timer.
    const generation = (flow.get('fullCycleTimerGeneration') || 0) + 1;
    flow.set('fullCycleTimerGeneration', generation);

    // Clear stored expiration.
    flow.set('fullCycleEnd', 0);

    // Kill the currently running interval.
    const oldTimer = flow.get('fullCycleTimerHandle');
    if (oldTimer) {
        clearInterval(oldTimer);
        flow.set('fullCycleTimerHandle', null);
    }

    // No status when timer is cleared.
    node.status({});

    return null;
}

// ------------------------------------------------------------
// STOP ANY PREVIOUS INSTANCE
// ------------------------------------------------------------

const oldTimer = flow.get('fullCycleTimerHandle');

if (oldTimer) {
    clearInterval(oldTimer);
    flow.set('fullCycleTimerHandle', null);
}

// ------------------------------------------------------------
// NEW GENERATION
// ------------------------------------------------------------

const generation =
    (flow.get('fullCycleTimerGeneration') || 0) + 1;

flow.set('fullCycleTimerGeneration', generation);

// ------------------------------------------------------------
// DETERMINE END TIME
// ------------------------------------------------------------

let end = Number(flow.get('fullCycleEnd'));

if (!restoring || !Number.isFinite(end) || end <= 0) {
    end = Date.now() + duration;
    flow.set('fullCycleEnd', end);
}

// ------------------------------------------------------------
// ALREADY EXPIRED
// ------------------------------------------------------------

if (end <= Date.now()) {

    flow.set('fullCycleEnd', 0);
    flow.set('fullCycleTimerHandle', null);

    node.status({});

    node.send({payload: "done"});

    return null;
}

// ------------------------------------------------------------
// UPDATE STATUS
// ------------------------------------------------------------

node.status({
    fill: "green",
    shape: "ring",
    text: restoring
        ? "14-day timer restored"
        : "Starting 14-day timer"
});

// ------------------------------------------------------------
// SINGLE ACTIVE INTERVAL
// ------------------------------------------------------------

const check = setInterval(() => {

    // Make sure this is still the active timer.
    if (
        flow.get('limitedMode') !== true ||
        flow.get('balanceHold') === true ||
        flow.get('fullCycleTimerGeneration') !== generation ||
        Number(flow.get('fullCycleEnd')) !== end
    ) {
        clearInterval(check);

        // Only clear our own stored handle.
        if (flow.get('fullCycleTimerHandle') === check) {
            flow.set('fullCycleTimerHandle', null);
            node.status({});
        }

        return;
    }

    const remaining = Math.max(0, end - Date.now());

    // --------------------------------------------------------
    // TIMER FINISHED
    // --------------------------------------------------------

    if (remaining <= 0) {

        clearInterval(check);

        flow.set('fullCycleEnd', 0);
        flow.set('fullCycleTimerHandle', null);

        node.status({});

        node.send({payload: "done"});

        return;
    }

    // --------------------------------------------------------
    // DISPLAY REMAINING TIME
    // --------------------------------------------------------

    const days = Math.floor(
        remaining / (24 * 60 * 60 * 1000)
    );

    const hours = Math.floor(
        (remaining % (24 * 60 * 60 * 1000)) /
        (60 * 60 * 1000)
    );

    node.status({
        fill: "green",
        shape: "ring",
        text: days + "d " + hours + "h left"
    });

}, 30000);

// Store the ONLY active timer handle.
flow.set('fullCycleTimerHandle', check);

return null;

// Cell-voltage charge-current limiter
//
// NORMAL MODE, and LIMITED MODE while the 30 -> 80 % charge window is open:
//   Applies the cell-voltage current curve (max 15 A, 0 A at 3.500 V).
//
// HYSTERESIS:
//   Limiter activates at >= 3.350 V and releases at <= 3.340 V.
//   Between 3.340 V and 3.350 V while active, it holds 15 A
//   so DVCC does not bounce 15 A -> 100 A -> 15 A.
//
// LIMITED MODE, WINDOW CLOSED (SOC logic already holds DVCC at 0 A):
//   Ignores cell voltage until it falls to <= 3.330 V, then clears
//   the cell limit so SOC stays authoritative.
//
// RATE LIMIT:
//   Current reductions are applied immediately.
//   Current increases are allowed at most once every 5 seconds.
//   Output is rounded down to whole amps to reduce settings writes.
//
// FAIL-SAFE:
//   A reading that is not a real number between 2.000 V and 4.000 V
//   (null, blank, true/false, 0, text, etc.) is treated as a fault:
//   cell current is forced to 0 A until a valid reading arrives.
//   A separate watchdog node does the same if readings stop arriving.

const points = [
    { v: 3.350, a: 30 },
    { v: 3.375, a: 20 },
    { v: 3.400, a: 10 },
    { v: 3.425, a: 5 },
    { v: 3.450, a: 2 },
    { v: 3.500, a: 0 }
];

const ACTIVATE_VOLTAGE = 3.350;
const RELEASE_VOLTAGE = 3.340;
const RESTART_VOLTAGE = 3.330;
const MAX_CELL_CURRENT = 15;
const INCREASE_INTERVAL = 5000;

const MIN_VALID_VOLTAGE = 2.000;
const MAX_VALID_VOLTAGE = 4.000;

const now = Date.now();
const raw = msg.payload;

// Accept only a real number, or a numeric string. Number(null),
// Number(""), Number(false) and Number([]) all give 0, which must
// never be read as a low cell voltage.
let voltage = NaN;
if (typeof raw === "number") {
    voltage = raw;
} else if (typeof raw === "string" && raw.trim() !== "") {
    voltage = Number(raw);
}

if (
    !Number.isFinite(voltage) ||
    voltage < MIN_VALID_VOLTAGE ||
    voltage > MAX_VALID_VOLTAGE
) {
    const alreadyFaulted =
        flow.get('cellFault') === true &&
        flow.get('desiredCell') === 0;

    flow.set('cellFault', true);
    flow.set('cellLimiterActive', true);

    node.status({
        fill:"red",
        shape:"dot",
        text:"FAULT: invalid cell voltage (" +
             JSON.stringify(raw) + ") → 0 A"
    });

    if (alreadyFaulted) return null;

    flow.set('desiredCell', 0);
    flow.set('lastCellSend', now);
    return {payload:"recalc"};
}

// Valid reading: record it for the watchdog and clear any fault.
// The 0 A fault limit stays in place until the normal logic below
// replaces it (increases are still rate-limited).
flow.set('lastCellRx', now);
flow.set('cellFault', false);

// ------------------------------------------------------------
// HELPERS
// ------------------------------------------------------------

// Remove the cell limit. Only triggers a recalc if a limit was set.
function clearLimit(text) {
    const prev = flow.get('desiredCell');
    const hadLimit = prev !== undefined && prev !== null;

    flow.set('cellLimiterActive', false);

    node.status({ fill:"grey", shape:"ring", text: text });

    if (!hadLimit) return null;

    flow.set('desiredCell', undefined);
    flow.set('lastCellSend', now);
    return {payload:"recalc"};
}

// Apply a cell limit. Reductions go out immediately;
// increases wait until 5 s after the last change.
function applyLimit(target, colour, label) {
    const prev = flow.get('desiredCell');
    const hasPrev = prev !== undefined && prev !== null;
    const text = voltage.toFixed(3) + " V → " + target + " A" + label;

    if (hasPrev && target === prev) {
        node.status({ fill:colour, shape:"dot", text: text });
        return null;
    }

    const isIncrease = hasPrev && target > prev;
    const lastSend = flow.get('lastCellSend') || 0;

    if (isIncrease && now - lastSend < INCREASE_INTERVAL) {
        node.status({
            fill:"blue",
            shape:"ring",
            text: voltage.toFixed(3) + " V → " + target +
                  " A (increase waiting 5s)"
        });
        return null;
    }

    flow.set('desiredCell', target);
    flow.set('lastCellSend', now);

    node.status({ fill:colour, shape:"dot", text: text });

    return {payload:"recalc"};
}

// ============================================================
// LIMITED MODE, CHARGE WINDOW CLOSED
// ============================================================

if (flow.get('limitedMode') === true && flow.get('windowOpen') !== true) {

    // Stay inactive while voltage is above 3.330 V.
    if (voltage > RESTART_VOLTAGE) {
        node.status({
            fill:"grey",
            shape:"ring",
            text: voltage.toFixed(3) +
                  " V — limited mode, waiting ≤ 3.330 V"
        });
        return null;
    }

    // Restart point reached: clear any leftover limit.
    return clearLimit(voltage.toFixed(3) + " V — cell limiter resumed");
}

// ============================================================
// NORMAL MODE / LIMITED-MODE CHARGE WINDOW — HYSTERESIS
// ============================================================

let cellLimiterActive = flow.get('cellLimiterActive') === true;

// If limiter is inactive, it activates at 3.350 V.
if (!cellLimiterActive) {

    if (voltage < ACTIVATE_VOLTAGE) {
        return clearLimit(voltage.toFixed(3) + " V (no cell limit)");
    }

    cellLimiterActive = true;
    flow.set('cellLimiterActive', true);
}

// Active limiter releases only at 3.340 V.
if (voltage <= RELEASE_VOLTAGE) {
    return clearLimit(voltage.toFixed(3) + " V — cell limiter released");
}

// 3.340–3.350 V band while active: hold 15 A.
if (voltage < ACTIVATE_VOLTAGE) {
    return applyLimit(MAX_CELL_CURRENT, "yellow", " (hysteresis)");
}

// ============================================================
// NORMAL CELL CURVE
// ============================================================

let current;

if (voltage >= points[points.length - 1].v) {

    current = 0;

} else {

    let i = 0;

    while (
        i < points.length - 1 &&
        voltage > points[i + 1].v
    ) {
        i++;
    }

    const p0 = points[Math.max(i - 1, 0)];
    const p1 = points[i];
    const p2 = points[i + 1];
    const p3 = points[Math.min(i + 2, points.length - 1)];

    const t = (voltage - p1.v) / (p2.v - p1.v);

    const m1 = 0.5 * (p2.a - p0.a);
    const m2 = 0.5 * (p3.a - p1.a);

    const t2 = t * t;
    const t3 = t2 * t;

    const a = 2 * t3 - 3 * t2 + 1;
    const b = t3 - 2 * t2 + t;
    const c = t3 - t2;
    const d = -2 * t3 + 3 * t2;

    current =
        a * p1.a +
        b * m1 +
        c * m2 +
        d * p2.a;

    current = Math.max(0, Math.min(MAX_CELL_CURRENT, current));
    current = Math.floor(current);
}

return applyLimit(current, "green", "");

const soc = flow.get('desiredSOC');
const cell = flow.get('desiredCell');

let final;
if (cell === undefined || cell === null) {
    final = (soc === undefined || soc === null) ? 100 : soc;
} else {
    final = Math.min(soc ?? 100, cell);
}

final = Math.max(0, Math.min(100, final));
final = Math.round(final * 10) / 10;

const last = flow.get('lastDVCC');

if (last === final) {
    node.status({
        fill: final === 0 ? "red" : (final >= 50 ? "green" : "yellow"),
        shape: "dot",
        text: "DVCC " + final + " A (unchanged)"
    });
    return null;
}

flow.set('lastDVCC', final);
msg.payload = final;

node.status({
    fill: final === 0 ? "red" : (final >= 50 ? "green" : "yellow"),
    shape: "dot",
    text: "DVCC → " + final + " A"
});

return msg;

// RESTORE CONTROL STATE
// Runs once when this flow starts (Node-RED start or full deploy),
// and can also be triggered manually from the inject button.
// Re-arms whichever timer the saved flow state says should be running,
// then forces DVCC to be rewritten.

const balanceHold = flow.get('balanceHold') === true;
const limitedMode = flow.get('limitedMode') === true;

const out = [null, null, null];
let text = "Normal mode";

if (balanceHold && !limitedMode) {
    out[0] = {payload: "restore_balance"};
    text = "Restored 2-hour balance";
} else if (limitedMode && !balanceHold) {
    out[1] = {payload: "restore_14day"};
    text = "Restored limited mode + 14-day timer";
}

// Make the Final Decision node write DVCC even if unchanged.
flow.set('lastDVCC', undefined);
out[2] = {payload: "recalc"};

node.status({fill: "blue", shape: "dot", text: text});

return out;

// CELL-VOLTAGE WATCHDOG
// If no valid max-cell-voltage reading has arrived within
// CELL_TIMEOUT, force the cell limit to 0 A (fail-safe).
// Also runs at startup: until the first valid reading arrives,
// charging is held at 0 A.
// The Cell Reduction Formula node clears the fault on the next
// valid reading.

const CELL_TIMEOUT = 60 * 1000;   // ms — see note on update rate

const now = Date.now();
const last = Number(flow.get('lastCellRx'));
const age = Number.isFinite(last) && last > 0 ? now - last : Infinity;

if (age <= CELL_TIMEOUT) {
    node.status({
        fill: "green",
        shape: "dot",
        text: "Cell data OK (" + Math.round(age / 1000) + " s old)"
    });
    return null;
}

const text = Number.isFinite(age)
    ? "FAULT: no cell data for " + Math.round(age / 1000) + " s → 0 A"
    : "FAULT: no cell data yet → 0 A";

node.status({ fill: "red", shape: "dot", text: text });

// Already faulted at 0 A: nothing to send.
if (flow.get('cellFault') === true && flow.get('desiredCell') === 0) {
    return null;
}

flow.set('cellFault', true);
flow.set('cellLimiterActive', true);
flow.set('desiredCell', 0);
flow.set('lastCellSend', now);

return {payload: "recalc"};

// DVCC READ-BACK CHECK
// Compares the actual GX setting with the value this flow last wrote.
// If they differ (write lost, or changed manually on the GX/VRM),
// forces Final Decision to write again.
// Rewrites are limited to once every 30 s so a mismatch can never
// turn into a rapid write loop.

const TOLERANCE = 0.5;        // A
const MIN_REWRITE_GAP = 30000; // ms

const actual = Number(msg.payload);
const expected = flow.get('lastDVCC');

if (typeof msg.payload !== "number" || !Number.isFinite(actual)) {
    node.status({fill: "red", shape: "ring", text: "invalid read-back: " + JSON.stringify(msg.payload)});
    return null;
}

if (expected === undefined || expected === null) {
    node.status({fill: "grey", shape: "ring", text: "GX " + actual + " A (nothing written yet)"});
    return null;
}

if (Math.abs(actual - expected) <= TOLERANCE) {
    node.status({fill: "green", shape: "dot", text: "GX " + actual + " A = flow " + expected + " A"});
    return null;
}

const now = Date.now();
const lastRewrite = flow.get('lastDvccRewrite') || 0;

if (now - lastRewrite < MIN_REWRITE_GAP) {
    node.status({fill: "yellow", shape: "ring", text: "GX " + actual + " A ≠ flow " + expected + " A (waiting)"});
    return null;
}

flow.set('lastDvccRewrite', now);
flow.set('lastDVCC', undefined);   // defeat the "unchanged" check

node.status({fill: "yellow", shape: "dot", text: "GX " + actual + " A ≠ flow " + expected + " A → rewriting"});

return {payload: "recalc"};
